mapper.sql:
WHERE e.clan_id = #{criteria.clanId}
  AND e.deleted_at IS NULL
  AND e.branch_id IN

    #{id}



  AND e.branch_id IN

    #{v}




  AND e.founder_person_id = #{criteria.founderPersonId}



  AND e.data_status IN

    #{v}




  AND e.privacy_level = #{criteria.privacyLevel}



  AND lower(coalesce(e.from_location, ''))
      LIKE concat('%', lower(#{criteria.fromLocation}), '%')



  AND lower(coalesce(e.to_location, ''))
      LIKE concat('%', lower(#{criteria.toLocation}), '%')



  AND lower(coalesce(e.migration_time_text, ''))
      LIKE concat('%', lower(#{criteria.migrationTimeText}), '%')



  AND (
    lower(coalesce(e.from_location, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
    OR lower(coalesce(e.to_location, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
    OR lower(coalesce(e.migration_time_text, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
    OR lower(coalesce(e.reason, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
    OR lower(coalesce(e.description, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
  )


AND (
  (
    e.privacy_level NOT IN ('relatives_only', 'private', 'sealed')
    AND e.sensitive_level NOT IN ('sensitive', 'highly_sensitive')
  )
  OR e.created_by = #{criteria.actorId}

    OR e.branch_id IN

      #{id}


)

mapper.select:
SELECT e.*
FROM migration_event e


LIMIT #{limit}
OFFSET #{offset}

SELECT EXISTS(
  SELECT 1
  FROM migration_event
  WHERE clan_id = #{clanId}
    AND branch_id = #{branchId}
    AND sequence_no = #{sequenceNo}
    AND deleted_at IS NULL

      AND id <> #{excludedId}

)
